export const MAP_FORMAT='silvengard-map-edits-v1';
export const SPECIES=['auto','conifer','broadleaf','dead','tropical','acacia','none'];
const FIELDS=['state','biome','woodland','vegetation','snow','aridity','region','cultureOverride','religionOverride'];
const snapshot=c=>Object.fromEntries(FIELDS.filter(k=>Object.hasOwn(c,k)).map(k=>[k,c[k]]));
function restore(c,s){for(const k of FIELDS){if(Object.hasOwn(s,k))c[k]=s[k];else delete c[k];}}
export function biomeValues(id){return {biome:id,vegetation:'auto',woodland:id===12?.55:id===13?1:[4,10].includes(id)?.15:1,snow:({9:.35,10:.55,11:1})[id]||0,aridity:[1,2].includes(id)?1:0,region:''};}
export function validateMapEdits(raw,D){
 if(raw?.format!==MAP_FORMAT||!Array.isArray(raw.cells)||raw.cells.length>D.cells.length)throw Error('Edição cartográfica inválida');
 if(!Number.isFinite(raw.grid?.stepX)||!Number.isFinite(raw.grid?.stepY)||raw.baseRevision!==D.revision||raw.grid?.columns!==D.grid.columns||raw.grid?.rows!==D.grid.rows||Math.abs(raw.grid.stepX-D.grid.stepX)>1e-6||Math.abs(raw.grid.stepY-D.grid.stepY)>1e-6)throw Error('Esta edição pertence a outra versão da malha do mapa. Guarde o arquivo para adaptação.');
 const countries=new Set(D.states.map(s=>s.i)),ids=new Set();const cells=raw.cells.map(v=>{if(!Number.isInteger(v.i)||v.i<0||v.i>=D.cells.length||D.cells[v.i].h<20||ids.has(v.i))throw Error('Célula inválida ou duplicada na edição');ids.add(v.i);const p={i:v.i};for(const key of Object.keys(v)){if(key==='i')continue;if(!FIELDS.includes(key))throw Error('Campo cartográfico desconhecido: '+key);const value=v[key];if(key==='state'&&(!Number.isInteger(value)||!countries.has(value)))throw Error('Estado desconhecido');if(key==='cultureOverride'&&(!Number.isInteger(value)||value!==-1&&!(D.cultures||[]).some(c=>c.i===value)))throw Error('Cultura inválida');if(key==='religionOverride'&&(!Number.isInteger(value)||value!==-1&&!(D.religions||[]).some(r=>r.i===value)))throw Error('Religião inválida');if(key==='biome'&&(!Number.isInteger(value)||value<1||value>16))throw Error('Bioma inválido');if(['woodland','snow','aridity'].includes(key)&&(!Number.isFinite(value)||value<0||value>(key==='woodland'?2:1)))throw Error('Densidade ou clima inválido');if(key==='vegetation'&&!SPECIES.includes(value))throw Error('Vegetação inválida');if(key==='region'&&(typeof value!=='string'||value.length>150))throw Error('Nome geográfico inválido');p[key]=value;}return p;});return {format:MAP_FORMAT,baseRevision:D.revision,grid:{...D.grid},cells};
}
export function createMapEditor(D){
 const base=new Map(),undo=[],redo=[];let stroke=null;
 function remember(i){if(!base.has(i))base.set(i,snapshot(D.cells[i]));}
 function begin(){if(stroke)throw Error('Pincel já ativo');stroke=new Map();}
 function paint(x,y,r,values){if(!stroke)throw Error('Inicie uma pincelada');const g=D.grid,changed=[];for(let cy=Math.max(0,Math.floor((y-r)/g.stepY));cy<=Math.min(g.rows-1,Math.floor((y+r)/g.stepY));cy++)for(let cx=Math.max(0,Math.floor((x-r)/g.stepX));cx<=Math.min(g.columns-1,Math.floor((x+r)/g.stepX));cx++){const c=D.cells[cy*g.columns+cx];if(c.h<20||Math.hypot(c.p[0]-x,c.p[1]-y)>r)continue;if(Object.entries(values).every(([k,v])=>c[k]===v))continue;remember(c.i);if(!stroke.has(c.i))stroke.set(c.i,snapshot(c));Object.assign(c,values);changed.push(c.i);}return changed;}
 function end(){if(!stroke)return [];const action=[...stroke].map(([i,before])=>({i,before,after:snapshot(D.cells[i])}));stroke=null;if(action.length){undo.push(action);if(undo.length>60)undo.shift();redo.length=0;}return action.map(a=>a.i);}
 function go(from,to,side){if(stroke)end();const a=from.pop();if(!a)return [];for(const s of a)restore(D.cells[s.i],s[side]);to.push(a);return a.map(s=>s.i);}
 function exportData(){return {format:MAP_FORMAT,baseRevision:D.revision,grid:{...D.grid},cells:[...base].flatMap(([i,b])=>{const c=snapshot(D.cells[i]),diff={};for(const k of FIELDS)if(c[k]!==b[k]&&Object.hasOwn(c,k))diff[k]=c[k];return Object.keys(diff).length?[{i,...diff}]:[];}).sort((a,b)=>a.i-b.i)};}
 function importData(raw){const clean=validateMapEdits(raw,D);if(stroke)end();const touched=new Set([...base.keys(),...clean.cells.map(c=>c.i)]),action=[...touched].map(i=>({i,before:snapshot(D.cells[i])}));for(const [i,b]of base)restore(D.cells[i],b);for(const p of clean.cells){remember(p.i);const {i,...values}=p;Object.assign(D.cells[i],values);}for(const a of action)a.after=snapshot(D.cells[a.i]);if(action.length){undo.push(action);if(undo.length>60)undo.shift();redo.length=0;}return [...touched];}
 return {begin,paint,end,exportData,importData,undo:()=>go(undo,redo,'before'),redo:()=>go(redo,undo,'after'),get canUndo(){return undo.length>0},get canRedo(){return redo.length>0}};
}
